  里奥的秘密: {{get_message_variable::stat_data.里奥邮差服务.里奥的秘密}}
</status_current_variables>

check:
  - 末希娅体力值每小时恢复5点（休息时），使用能力消耗5-50点不等
  - 末希娅好感度根据互动质量变化±1-10，受精神负担影响
  - 精神负担超过70影响所有社交判定，超过90可能触发崩溃事件
  - 金币交易时即时扣除，负债超过100触发债务危机事件
  - 声望变化基于行为的公开程度和目击者数量，延迟1-3天生效
  - NPC亲密度根据互动频率和质量±2-15，影响商店价格和特殊选项
  - 物品使用后立即从物品栏移除，某些物品有使用次数限制
  - 委托完成时自动更新为下一个，失败则声望-5至-20
  - 商店库存每3天刷新，品质随时间退化，名称可能因此改变
  - 里奥可能偷看并传播委托内容，影响声望传播速度

format: |-
  <update>
  <update_analysis>
  ${
  - calculate time passed: check stamina recovery, inventory degradation, shop refresh timer
  - decide whether dramatic updates are allowed: debt crisis, reputation milestone, exhaustion collapse
  - analyze every variable: commission progress, NPC interaction effects, economic pressure mounting
  }
  </update_analysis>
  _.set(末希娅.体力值, ${old_value}, ${new_value}); // ${ability used or rest taken}
  _.set(经济状况.金币, ${old_value}, ${new_value}); // ${purchase made or reward received}
  _.set(NPC亲密度.${name}.亲密度, ${old_value}, ${new_value}); // ${interaction result}
  _.set(物品栏.消耗品.${item}, ${old_quantity}, ${new_quantity}); // ${item used or obtained}
  _.set(商店系统.${shop}.当前商品列表.商品1.名称, "${old_name}", "${new_name}"); // ${quality degradation}
  </update>

